      return speechProb;
    }

    if (speechProb < threshold - 0.15) {
      if (this._triggered) {
        if (this._tempEnd === 0) {
          this._tempEnd = this._currentSample;
        }
        if (
          this._currentSample - this._tempEnd >
          this.params.minSilenceSamplesAtMaxSpeech
        ) {
          this._prevEnd = this._tempEnd;
        }
        if (
          this._currentSample - this._tempEnd >=
